import { mkdirSync, readFileSync, writeFileSync } from "node:fs";

const artifactPath = "artifacts/contracts/StampRegistry.sol/StampRegistry.json";
const outDir = "packages/sdk/src/generated";
const outPath = `${outDir}/stampRegistryAbi.ts`;

const artifact = JSON.parse(readFileSync(artifactPath, "utf8"));

const body = `// GENERATED FILE. Do not edit by hand.
// Regenerated by tools/export-abi.mjs from the compiled contract artifact
// (\`hardhat compile\` then \`node tools/export-abi.mjs\`). CI recompiles and
// regenerates this file, then fails if \`git diff\` shows any change: the ABI
// here must never drift from contracts/StampRegistry.sol.
export const stampRegistryAbi = ${JSON.stringify(artifact.abi, null, 2)} as const;
`;

mkdirSync(outDir, { recursive: true });
writeFileSync(outPath, body);
console.log(`Wrote ${outPath} from ${artifactPath}`);
